from pathlib import Path
import sys,json,subprocess,runpy
root=Path(sys.argv[1]);runpy.run_path(str(Path(__file__).with_name('certificate_pair_fixture.py')),run_name='__main__');store=root/'w';ledger=store/'observations.jsonl';public=store/'witness.pub';before=ledger.read_bytes();sample=json.loads(before.splitlines()[0])['body']['observation'];known={key:sample[key]for key in('host','port','vantage')};missing={'host':'missing.example','port':443,'vantage':'remote'};policy=root/'expected-policy.json';policy.write_text(json.dumps([known,missing]));original=policy.read_bytes()
def cli(*args):return subprocess.run([sys.executable,'-m','wireledger',*map(str,args)],capture_output=True,text=True)
base=['coverage',ledger,'--public-key',public,'--expected',policy,'--policy-picker'];r=cli(*base);assert r.returncode==2,r.stderr;(root/'picker.html').write_text(r.stdout);(root/'expected.json').write_text(json.dumps([missing]))
policy.write_text(json.dumps([known,missing,{'host':'bad.example','port':True,'vantage':'remote'}]));r=cli(*base);assert r.returncode==1 and not r.stdout;policy.write_bytes(original);ledger.write_bytes(before.replace(b'localhost',b'tampered'));r=cli(*base);assert r.returncode==1 and not r.stdout;ledger.write_bytes(before)
policy.write_text(json.dumps([known]));r=cli(*base,'--attention-only');assert r.returncode==0,r.stderr;assert 'No rows match' in r.stdout;policy.write_bytes(original)
code="from unittest.mock import patch;from wireledger.__main__ import main\nwith patch('socket.getaddrinfo',side_effect=RuntimeError('DNS forbidden')),patch('wireledger.__main__.load_private',side_effect=RuntimeError('key forbidden')):raise SystemExit(main("+repr(list(map(str,base)))+"))";assert subprocess.run([sys.executable,'-c',code],capture_output=True).returncode==2;assert ledger.read_bytes()==before and policy.read_bytes()==original
